// (1) The phases, in order, for a typical build:
//   entry -> resolve imports -> transform (TS/JSX -> JS) -> bundle -> optimize
//     -> minified, tree-shaken, code-split output in dist/.

// (2) Tree shaking: only ESM (import/export) is statically analyzable.
//   // utils.ts
//   export function used() { /* ... */ }
//   export function unused() { /* ... */ }   // DROPPED if nothing imports it
//   // app.ts
//   import { used } from './utils';        // only `used` is in the bundle
//   //   CommonJS `require` can't be tree-shaken (dynamic) -> ESM matters.

// (3) Code splitting: load a route's code only when visited.
//   const Admin = lazy(() => import('./Admin'));   // separate chunk
//   //   The admin bundle downloads on first navigation, not at startup.

// (4) The Vite-vs-Webpack dev difference:
//   Webpack: bundles the whole app on every dev start -> slower as it grows.
//   Vite: serves source via NATIVE browser ESM; the browser requests each
//     module on demand; Vite transforms on the fly -> near-instant startup
//     regardless of app size. Production build uses Rollup.
